.pj-actions .btn { font-size: 12px; padding: 5px 11px; }
.pj-actions .btn:disabled { opacity: .45; cursor: default; transform: none; }
.pj-actions .btn.primary:disabled { filter: saturate(.4); }
.btn.danger-ghost { background: transparent; border-color: #5a2a2d; color: #ff9b9e; }
