/* FableCut loudness measurement — ITU-R BS.1770-4 integrated loudness (LUFS,
   EBU R128 gating) and sample peak. Zero dependencies. Loaded by the editor as
   a plain script (global `FableCutLoudness`) and required by the MCP server,
   so Normalize in the UI and `fablecut_normalize_audio` measure identically.

   A clip is measured AFTER its channel routing (audioChannel / channelMode)
   and BEFORE gain, volume and pan: equal-power pan keeps BS.1770 loudness, so
   the reading holds wherever the clip is panned. */
(function (root, factory) {
  const api = factory();
  if (typeof module === "object" && module.exports) module.exports = api;
  else root.FableCutLoudness = api;
})(typeof self !== "undefined" ? self : this, function () {
  "use strict";

  /* K-weighting: stage 1 high shelf + stage 2 RLB high-pass, with the
     BS.1770 analog prototypes re-derived for any sample rate (same values the
     meter worklet uses). */
  function shelfCoeffs(fs) {
    const f0 = 1681.974450955533, G = 3.999843853973347, Q = 0.7071752369554196;
    const K = Math.tan(Math.PI * f0 / fs);
    const Vh = Math.pow(10, G / 20), Vb = Math.pow(Vh, 0.5);
    const a0 = 1 + K / Q + K * K;
    return {
      b0: (Vh + Vb * K / Q + K * K) / a0, b1: 2 * (K * K - Vh) / a0,
      b2: (Vh - Vb * K / Q + K * K) / a0, a1: 2 * (K * K - 1) / a0, a2: (1 - K / Q + K * K) / a0,
    };
  }
  function hpfCoeffs(fs) {
    const f0 = 38.13547087613982, Q = 0.5003270373238773;
    const K = Math.tan(Math.PI * f0 / fs);
    const a0 = 1 + K / Q + K * K;
    return { b0: 1 / a0, b1: -2 / a0, b2: 1 / a0, a1: 2 * (K * K - 1) / a0, a2: (1 - K / Q + K * K) / a0 };
  }
  function biquad(c) { return { ...c, z1: 0, z2: 0 }; }

  const ABS_GATE = -70;     // LUFS
  const REL_GATE = -10;     // LU below the abs-gated mean
  const loud = (ms) => -0.691 + 10 * Math.log10(ms);

  /** Streaming meter: push() channel arrays of equal length as audio arrives,
   *  then result(). Every channel is weighted 1 (mono / stereo programme). */
  class LoudnessMeter {
    constructor(channels, sampleRate) {
      this.fs = sampleRate;
      this.step = Math.max(1, Math.round(sampleRate * 0.1)); // 100 ms hop, 400 ms blocks (75% overlap)
      this.filters = [];
      for (let i = 0; i < channels; i++)
        this.filters.push([biquad(shelfCoeffs(sampleRate)), biquad(hpfCoeffs(sampleRate))]);
      this.sub = [];      // K-weighted energy per 100 ms step, summed over channels
      this.acc = 0;       // energy of the step being filled
      this.fill = 0;      // samples in the step being filled
      this.tail = 0;      // energy of everything (fallback for < 400 ms)
      this.n = 0;
      this.peak = 0;
    }
    push(chs) {
      const len = chs.length ? chs[0].length : 0;
      for (let i = 0; i < len; i++) {
        let e = 0;
        for (let c = 0; c < chs.length && c < this.filters.length; c++) {
          const x = chs[c][i];
          const a = x < 0 ? -x : x;
          if (a > this.peak) this.peak = a;
          const [s, h] = this.filters[c];
          let y = s.b0 * x + s.z1;
          s.z1 = s.b1 * x - s.a1 * y + s.z2; s.z2 = s.b2 * x - s.a2 * y;
          const x2 = y;
          y = h.b0 * x2 + h.z1;
          h.z1 = h.b1 * x2 - h.a1 * y + h.z2; h.z2 = h.b2 * x2 - h.a2 * y;
          e += y * y;
        }
        this.acc += e;
        this.tail += e;
        if (++this.fill === this.step) { this.sub.push(this.acc); this.acc = 0; this.fill = 0; }
      }
      this.n += len;
    }
    /** {lufs, peak, peakDb}: lufs is -Infinity for silence, peak is linear. */
    result() {
      const blocks = [];
      for (let j = 0; j + 4 <= this.sub.length; j++)
        blocks.push((this.sub[j] + this.sub[j + 1] + this.sub[j + 2] + this.sub[j + 3]) / (4 * this.step));
      // Shorter than one 400 ms block: gate the whole clip as a single block.
      if (!blocks.length && this.n > 0) blocks.push(this.tail / this.n);
      const absGated = blocks.filter((z) => z > 0 && loud(z) > ABS_GATE);
      let lufs = -Infinity;
      if (absGated.length) {
        const rel = loud(absGated.reduce((a, b) => a + b, 0) / absGated.length) + REL_GATE;
        const gated = absGated.filter((z) => loud(z) > rel);
        if (gated.length) lufs = loud(gated.reduce((a, b) => a + b, 0) / gated.length);
      }
      const peakDb = this.peak > 0 ? 20 * Math.log10(this.peak) : -Infinity;
      return { lufs, peak: this.peak, peakDb };
    }
  }

  function measure(chs, sampleRate) {
    const m = new LoudnessMeter(chs.length, sampleRate);
    m.push(chs);
    return m.result();
  }

  const CHANNEL_MODES = ["stereo", "mono", "left", "right", "swap"];

  /** What a clip sends into its gain stage, as channel arrays. Mirrors the
   *  editor's audio graph: an isolated stem (audioChannel) or a mono mode is
   *  one channel (pan places it with equal power); stereo/swap keep them all. */
  function routeChannels(chs, { audioChannel, channelMode } = {}) {
    if (!chs.length) return [];
    if (Number.isInteger(audioChannel) && audioChannel >= 0)
      return audioChannel < chs.length ? [chs[audioChannel]] : [];
    const mode = CHANNEL_MODES.includes(channelMode) ? channelMode : "stereo";
    if (chs.length === 1) return [chs[0]];
    if (mode === "left") return [chs[0]];
    if (mode === "right") return [chs[1]];
    if (mode === "swap") return [chs[1], chs[0], ...chs.slice(2)];
    if (mode === "mono") {
      const n = chs[0].length, out = new Float32Array(n), k = 1 / chs.length;
      for (const x of chs) for (let i = 0; i < n; i++) out[i] += x[i] * k;
      return [out];
    }
    return chs;
  }

  /** Gain (dB) that brings a measurement to `target` ({mode:"lufs"|"peak", value}).
   *  null when the clip is silent — nothing to normalize. */
  function normalizeGainDb(m, target) {
    const level = target.mode === "peak" ? m.peakDb : m.lufs;
    if (!Number.isFinite(level)) return null;
    return target.value - level;
  }

  return { LoudnessMeter, measure, routeChannels, normalizeGainDb, CHANNEL_MODES, shelfCoeffs, hpfCoeffs };
});

files.ducking.js:
/* FableCut auto-duck — find where the voice is and turn that into `duck`
   keyframes (dB) on the music. Zero dependencies; loaded by the editor as a
   plain script (global `FableCutDucking`) and required by the MCP server, so
   the inspector's Auto-duck and `fablecut_auto_duck` write identical keys.

   Pipeline: rmsEnvelope (per voice clip) → activeRegions (timeline seconds,
   above a threshold) → mergeRegions (all voices, short gaps bridged) →
   duckKeyframes (ramps down before speech, back up after). */
(function (root, factory) {
  const api = factory();
  if (typeof module === "object" && module.exports) module.exports = api;
  else root.FableCutDucking = api;
})(typeof self !== "undefined" ? self : this, function () {
  "use strict";

  const HOP = 0.05;  // s between envelope points
  const WIN = 0.1;   // s RMS window

  /** Streaming RMS envelope over one or more channels (power summed, so a
   *  stereo voice reads like its loudness). push() as audio arrives. */
  class EnvelopeMeter {
    constructor(channels, sampleRate, hop = HOP, win = WIN) {
      this.c = channels;
      this.hopN = Math.max(1, Math.round(hop * sampleRate));
      this.winN = Math.max(this.hopN, Math.round(win * sampleRate));
      this.ring = new Float64Array(this.winN); // per-sample power, last winN
      this.idx = 0; this.sum = 0; this.n = 0;
      this.out = [];
    }
    push(chs) {
      const len = chs.length ? chs[0].length : 0;
      for (let i = 0; i < len; i++) {
        let e = 0;
        for (let k = 0; k < chs.length; k++) { const x = chs[k][i]; e += x * x; }
        this.sum += e - this.ring[this.idx];
        this.ring[this.idx] = e;
        this.idx = (this.idx + 1) % this.winN;
        if (++this.n % this.hopN === 0)
          this.out.push(Math.sqrt(Math.max(0, this.sum) / Math.min(this.n, this.winN)));
      }
    }
    /** Linear RMS per hop; point i covers the window ending at (i + 1) × hop. */
    result() { return Float32Array.from(this.out); }
  }
  function rmsEnvelope(chs, sampleRate, hop = HOP) {
    const m = new EnvelopeMeter(chs.length, sampleRate, hop);
    m.push(chs);
    return m.result();
  }

  /** Timeline [start, end] spans where the envelope is above threshold.
   *  env[i] maps to timeline t0 + (i + 1) × hop / speed; `gain` (linear) is the
   *  clip's own gain × volume, so a quiet take still counts as voice. */
  function activeRegions(env, { t0 = 0, hop = HOP, speed = 1, gain = 1, threshold = -40, minLen = 0.25 } = {}) {
    const lim = Math.pow(10, threshold / 20);
    const step = hop / Math.max(0.01, speed);
    const out = [];
    let a = -1;
    for (let i = 0; i <= env.length; i++) {
      const on = i < env.length && env[i] * gain >= lim;
      if (on && a < 0) a = i;
      if (!on && a >= 0) {
        // the window ending at point a started WIN earlier — begin there
        const s = t0 + Math.max(0, (a + 1) * step - WIN / Math.max(0.01, speed));
        const e = t0 + i * step;
        if (e - s >= minLen) out.push([s, e]);
        a = -1;
      }
    }
    return out;
  }

  /** Union of region lists; gaps shorter than `gap` seconds are bridged so the
   *  music doesn't pump between words. */
  function mergeRegions(lists, gap = 0.6) {
    const all = lists.flat().filter((r) => r[1] > r[0]).sort((x, y) => x[0] - y[0]);
    const out = [];
    for (const [s, e] of all) {
      const last = out[out.length - 1];
      if (last && s <= last[1] + gap) last[1] = Math.max(last[1], e);
      else out.push([s, e]);
    }
    return out;
  }

  /** `duck` keyframes (clip-local seconds, dB) for one music clip.
   *  Ramps start `attack` s before each region and recover over `release` s
   *  after it; ramps that would meet stay ducked. Returns [] when no region
   *  touches the clip. */
  function duckKeyframes(regions, { start, duration }, { amount = -12, attack = 0.3, release = 0.6 } = {}) {
    amount = Math.min(0, +amount || 0);
    const end = start + duration;
    const spans = mergeRegions([regions.map(([s, e]) => [s - attack, e + release])], 0)
      .filter(([s, e]) => e > start && s < end);
    if (!spans.length || !amount) return [];
    // The envelope in timeline time: each span is 0 → amount (attack) → hold →
    // amount → 0 (release). A merged span always has attack-end ≤ release-start.
    const pts = [];
    for (const [s, e] of spans) pts.push([s, 0], [s + attack, amount], [e - release, amount], [e, 0]);
    const valAt = (t) => {
      if (t <= pts[0][0]) return pts[0][1];
      for (let i = 1; i < pts.length; i++) {
        const [t1, v1] = pts[i], [t0, v0] = pts[i - 1];
        if (t <= t1) return t1 > t0 ? v0 + (v1 - v0) * (t - t0) / (t1 - t0) : v1;
      }
      return pts[pts.length - 1][1];
    };
    // Cut it to the clip: interpolated values on the edges, corners inside.
    const r3 = (x) => Math.round(x * 1000) / 1000;
    const keys = [];
    const put = (t, v) => {
      t = r3(t - start); v = r3(v) || 0;
      const last = keys[keys.length - 1];
      if (last && t <= last.t) { last.v = v; return; } // same instant: latest wins
      keys.push({ t, v, ease: "linear" });
    };
    const v0 = valAt(start), v1 = valAt(end);
    if (v0) put(start, v0);
    for (const [t, v] of pts) if (t > start && t < end) put(t, v);
    if (v1) put(end, v1);
    // collapse runs of equal values to their two ends
    return keys.filter((k, i) => !(i > 0 && i < keys.length - 1 &&
      keys[i - 1].v === k.v && keys[i + 1].v === k.v));
  }

  return { HOP, WIN, EnvelopeMeter, rmsEnvelope, activeRegions, mergeRegions, duckKeyframes };
});

