     *  its linked group, which a roll moves together (a stem may sit on a shorter file) */
    const own = (c) => timed(c)
      ? { head: (c.in || 0) / speedOf(c), tail: Math.max(0, mediaDur(c) - c.duration * speedOf(c)) / speedOf(c) }
      : { head: Infinity, tail: Infinity };
