  function toSRT(list) {
    return list.map((c, i) => `${i + 1}\n${stamp(c.start, ",")} --> ${stamp(c.end, ",")}\n${c.text}\n`).join("\n");
  }
  /** WebVTT text. */
  function toVTT(list) {
    return "WEBVTT\n\n" + list.map((c) => `${stamp(c.start, ".")} --> ${stamp(c.end, ".")}\n${c.text}\n`).join("\n");
  }
  /** "01:02:03,456", "02:03.456" or "3.5" → seconds, or null. */
