      const why = c.kind !== "video" ? (ids ? `${/^[aeiou]/.test(c.kind) ? "an" : "a"} ${c.kind} clip` : null)
        : c.disabled || off.has(c.track) ? "disabled"
        : Array.isArray(c.keyframes?.speed) && c.keyframes.speed.length ? "a speed ramp"
        : null;
