/* FableCut sequences — several timelines in one project. Zero dependencies.
   Loaded by the editor as a plain script (global `FableCutSeq`) and required
   by the MCP server, project-ops and the tests.

   The OPEN sequence is the project's top level, as it always was: `clips`,
   `tracks`, `markers`, the canvas, the mix and the delivery settings. Every
   tool, agent and export keeps reading and writing those. The others are kept
   in `project.sequences`, each with its own copy of the same keys:

     "sequence": "main",                      // the open one
     "sequences": [
       { "id": "main", "name": "Main" },      // the open one: its timeline is the top level
       { "id": "seq_v", "name": "Vertical", "width": 1080, "height": 1920, "fps": 30, "clips": [ … ], … }
     ]

   Opening another sequence parks the top-level keys in the open one's entry
   and brings the other's up. Media, folders, collections and compositions
   are the project's, shared by every sequence. A project with one sequence
   has neither key: untouched projects stay byte-identical. */
(function (root, factory) {
  const node = typeof module === "object" && module.exports;
  const api = factory();
  if (node) module.exports = api;
  else root.FableCutSeq = api;
})(typeof self !== "undefined" ? self : this, function () {
  "use strict";

  /** What a sequence owns: its timeline, canvas, frame rate, mix and delivery. */
  const KEYS = ["width", "height", "fps", "background", "exportFrame", "clips", "tracks", "markers", "inPoint", "outPoint",
    "disabledTracks", "lockedTracks", "untargetedTracks", "master", "buses", "delivery", "outputs", "encodeProfile"];
  const MAIN = { id: "main", name: "Main" };
  const MAX = 64;
  const isObj = (v) => v != null && typeof v === "object" && !Array.isArray(v);
  const clone = (v) => (v === undefined ? undefined : JSON.parse(JSON.stringify(v)));
  const uid = () => Math.random().toString(36).slice(2, 8);
  const r2 = (v) => Math.round(v * 100) / 100;

  /** The sequence entries, the open one included (a project without the key has one: Main). */
  function entries(doc) {
    return doc && Array.isArray(doc.sequences) && doc.sequences.length ? doc.sequences : [{ ...MAIN }];
  }
  function activeId(doc) {
    const list = entries(doc);
    return doc && list.some((s) => s.id === doc.sequence) ? doc.sequence : list[0].id;
  }
  function find(doc, id) { return entries(doc).find((s) => s.id === id) || null; }
  /** The sequences that are not open: [{id, name, clips, …}] — media and comp usage scans read these too. */
  function others(doc) {
    const act = activeId(doc);
    return entries(doc).filter((s) => s.id !== act);
  }
  const lengthOf = (clips) => (Array.isArray(clips) ? clips : []).reduce((m, c) => Math.max(m, (+c.start || 0) + (+c.duration || 0)), 0);

  /** One row per sequence, in order: {id, name, active, width, height, fps, clips, duration}. */
  function list(doc) {
    const act = activeId(doc);
    return entries(doc).map((s) => {
      const src = s.id === act ? doc : s;
      return { id: s.id, name: s.name || s.id, active: s.id === act, width: src.width, height: src.height, fps: src.fps,
        clips: Array.isArray(src.clips) ? src.clips.length : 0, duration: r2(lengthOf(src.clips)) };
    });
  }

  /** Check and tidy doc.sequences in place (throws on a bad entry). One sequence named Main → both keys go. */
  function normalize(doc) {
    if (doc.sequences == null) { delete doc.sequence; return doc; }
    if (!Array.isArray(doc.sequences)) throw new Error("sequences must be a list of {id, name, …}");
    if (doc.sequences.length > MAX) throw new Error(`a project holds up to ${MAX} sequences`);
    const seen = new Set();
    const out = [];
    for (const s of doc.sequences) {
      if (!isObj(s)) throw new Error("every sequence is an object {id, name, …}");
      const id = typeof s.id === "string" ? s.id.trim().slice(0, 40) : "";
      if (!id) throw new Error("every sequence needs an id");
      if (seen.has(id)) throw new Error(`two sequences have the id ${id} — sequence ids must be unique`);
      seen.add(id);
      const name = typeof s.name === "string" && s.name.trim() ? s.name.trim().slice(0, 120) : id;
      out.push({ ...s, id, name });
    }
    if (!out.length) { delete doc.sequences; delete doc.sequence; return doc; }
    // without a valid `sequence`, the open one is an entry without a timeline of its own: never strip one that has one
    const named = out.some((s) => s.id === doc.sequence);
    const bare = out.find((s) => !KEYS.some((k) => s[k] !== undefined));
    if (!named && !bare) throw new Error(`sequence must name the open sequence (${out.map((s) => s.id).join(", ")}): every entry carries a timeline of its own`);
    const act = named ? doc.sequence : bare.id;
    for (const s of out) {
      if (s.id === act) { for (const k of KEYS) delete s[k]; continue; }
      // a parked sequence carries its own timeline
      if (s.clips == null) s.clips = [];
      if (!Array.isArray(s.clips)) throw new Error(`sequence ${s.id}: clips must be a list`);
      for (const c of s.clips) if (!isObj(c) || typeof c.id !== "string" || typeof c.start !== "number" || typeof c.duration !== "number")
        throw new Error(`sequence ${s.id}: every clip needs id, numeric start and duration`);
      for (const k of ["width", "height", "fps"]) if (s[k] != null && !(typeof s[k] === "number" && s[k] > 0)) throw new Error(`sequence ${s.id}: ${k} must be a positive number`);
    }
    if (out.length === 1 && out[0].id === MAIN.id && out[0].name === MAIN.name) { delete doc.sequences; delete doc.sequence; return doc; }
    doc.sequences = out;
    doc.sequence = act;
    return doc;
  }

  /** Make the list explicit (before adding to it). */
  function materialize(doc) {
    if (!Array.isArray(doc.sequences) || !doc.sequences.length) doc.sequences = [{ ...MAIN }];
    doc.sequence = activeId(doc);
    return doc;
  }
  /** The open sequence's keys, copied out of the top level. */
  function takeTop(doc) {
    const out = {};
    for (const k of KEYS) if (doc[k] !== undefined) out[k] = clone(doc[k]);
    if (!Array.isArray(out.clips)) out.clips = [];
    return out;
  }

  /** Open sequence `id`: the open one's timeline is parked in its entry, `id`'s comes up. */
  function open(doc, id) {
    const target = find(doc, id);
    if (!target) throw new Error(`no sequence ${id} (${entries(doc).map((s) => s.id).join(", ")})`);
    const act = activeId(doc);
    if (id === act) return doc;
    materialize(doc);
    const parked = takeTop(doc);
    const keep = { width: doc.width, height: doc.height, fps: doc.fps };
    doc.sequences = doc.sequences.map((s) => {
      if (s.id === act) return { id: s.id, name: s.name, ...parked };
      if (s.id === id) return { id: s.id, name: s.name };
      return s;
    });
    for (const k of KEYS) {
      if (target[k] !== undefined) doc[k] = target[k];
      else delete doc[k];
    }
    // a sequence always has a canvas and a timeline
    for (const k of ["width", "height", "fps"]) if (!(doc[k] > 0)) doc[k] = keep[k];
    if (!Array.isArray(doc.clips)) doc.clips = [];
    doc.sequence = id;
    return doc;
  }

  /** A new sequence: {name?, id?, from?: "empty" | "open" | <sequence id>, width?, height?, fps?}.
   *  Empty takes the open one's canvas, frame rate and background; a copy takes everything.
   *  It is added after the open one (or after `from`) and not opened. */
  function add(doc, opts = {}) {
    materialize(doc);
    const from = opts.from || "empty";
    const id = opts.id ? String(opts.id).trim().slice(0, 40) : "seq_" + uid();
    if (!id) throw new Error("addSequence: the id is empty");
    if (find(doc, id)) throw new Error(`addSequence: sequence ${id} already exists`);
    if (doc.sequences.length >= MAX) throw new Error(`addSequence: a project holds up to ${MAX} sequences`);
    const act = activeId(doc);
    let body, after = act;
    if (from === "empty") {
      body = { width: doc.width, height: doc.height, fps: doc.fps, clips: [] };
      if (doc.background) body.background = doc.background;
    } else if (from === "open" || from === act) {
      body = takeTop(doc);
    } else {
      const src = find(doc, from);
      if (!src) throw new Error(`addSequence: no sequence ${from} to copy`);
      const { id: _i, name: _n, ...rest } = clone(src);
      body = rest;
      after = src.id;
    }
    for (const k of ["width", "height", "fps"]) if (opts[k] != null) {
      const v = +opts[k];
      if (!(v > 0) || (k !== "fps" && (v < 16 || v > 8192)) || (k === "fps" && v > 240)) throw new Error(`addSequence: ${k} ${opts[k]} is out of range`);
      body[k] = k === "fps" ? v : Math.round(v);
    }
    if (from !== "empty" && (opts.width != null || opts.height != null)) delete body.exportFrame;   // the crop was for the other size
    const srcName = from === "empty" ? null : (find(doc, from === "open" ? act : from) || {}).name;
    const name = typeof opts.name === "string" && opts.name.trim() ? opts.name.trim().slice(0, 120)
      : srcName ? `${srcName} copy` : `Sequence ${doc.sequences.length + 1}`;
    const entry = { id, name, ...body };
    const at = doc.sequences.findIndex((s) => s.id === after);
    doc.sequences.splice(at + 1, 0, entry);
    return entry;
  }

  /** Rename (the only thing set on an entry — the open one's timeline is edited at the top level). */
  function rename(doc, id, name) {
    const s = find(doc, id);
    if (!s) throw new Error(`no sequence ${id}`);
    const n = String(name == null ? "" : name).trim().slice(0, 120);
    if (!n) throw new Error("a sequence needs a name");
    materialize(doc);
    doc.sequences = doc.sequences.map((x) => (x.id === id ? { ...x, name: n } : x));
    return normalize(doc);
  }
  /** Move sequence `id` to position `index` (0-based) in the list. */
  function move(doc, id, index) {
    materialize(doc);
    const i = doc.sequences.findIndex((s) => s.id === id);
    if (i < 0) throw new Error(`no sequence ${id}`);
    const [s] = doc.sequences.splice(i, 1);
    doc.sequences.splice(Math.max(0, Math.min(doc.sequences.length, Math.round(+index) || 0)), 0, s);
    return doc;
  }
  /** Delete sequence `id`. The last one stays; deleting the open one opens its neighbour first. */
  function remove(doc, id) {
    const list = entries(doc);
    const i = list.findIndex((s) => s.id === id);
    if (i < 0) throw new Error(`no sequence ${id}`);
    if (list.length === 1) throw new Error("a project keeps at least one sequence");
    if (activeId(doc) === id) open(doc, (list[i + 1] || list[i - 1]).id);
    doc.sequences = doc.sequences.filter((s) => s.id !== id);
    return normalize(doc);
  }

  /** One line per sequence, for status readouts. */
  function describe(row) {
    const t = Math.round(row.duration), m = Math.floor(t / 60), s = t % 60;
    return `${row.id} "${row.name}"${row.active ? " (open)" : ""} ${row.width}x${row.height}@${row.fps}, ${row.clips} clip(s), ${m}:${String(s).padStart(2, "0")}`;
  }

  return { KEYS, MAIN, MAX, entries, activeId, find, others, list, normalize, materialize, open, add, rename, move, remove, describe };
});

files.templates.js:
/* FableCut animation presets and templates. Zero dependencies. Loaded by the
   editor as a plain script (global `FableCutTemplates`) and required by the MCP
   server and the tests.

   A PRESET is a named animation that fits any visual clip:
     { id, name, group, anchor: "in" | "out" | "at" | "whole", length, keys: { channel: [{t, v, ease?}] }, props? }
   "in" plays from the clip's start, "out" ends at its end, "at" plays at a
   given time (an emphasis), "whole" spans the clip (a loop; its key times are
   fractions 0…1 of the clip). Key values are relative to the clip's own value
   of that channel at rest: `scale` and `opacity` multiply it, everything else
   adds to it. So "Slide up" works wherever the clip sits and however big it is.

   A TEMPLATE is a composition with editable fields:
     { id, name, group, width, height, duration, hold, background?, tracks?, clips, media?, fields }
   fields: [{ key, label, type: "text" | "color" | "media", default?, targets: ["<clip id>:<path>" | "comp:background"] }]
   Placing one makes its own comp (so two lower thirds can say different
   names) and records the field values in comp.template. `hold` is the time the
   exit animation starts: retime() keeps everything after it at the same
   distance from the end, so a longer template just holds longer. */
(function (root, factory) {
  const api = factory();
  if (typeof module === "object" && module.exports) module.exports = api;
  else root.FableCutTemplates = api;
})(typeof self !== "undefined" ? self : this, function () {
  "use strict";

  const isObj = (v) => v != null && typeof v === "object" && !Array.isArray(v);
  const isNum = (v) => typeof v === "number" && Number.isFinite(v);
  const r4 = (v) => +(+v).toFixed(4);
  const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
  const clone = (v) => JSON.parse(JSON.stringify(v));
  const slug = (s) => String(s || "").toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 60);
  const EPS = 1e-4;

  /* ── Presets ── */
  const EASES = ["linear", "ease-in", "ease-out", "ease-in-out"];
  const ANCHORS = ["in", "out", "at", "whole"];
  /** Channels a preset may key. scale and opacity multiply the clip's value; the rest add to it. */
  const CHANNELS = ["x", "y", "scale", "rotation", "opacity", "blur", "anchorX", "anchorY", "trimStart", "trimEnd", "trimOffset",
    "brightness", "saturation", "hue", "grayscale", "shake", "rgbSplit", "glow", "fontSize", "letterSpacing", "pathOffset"];
  const MULTIPLY = new Set(["scale", "opacity"]);
  const PRESET_PROPS = ["motionBlur", "motionBlurSamples"];
  const REST = { scale: 1, opacity: 1, brightness: 100, saturation: 100, trimEnd: 100 };

  const k = (t, v, ease) => (ease ? { t, v, ease } : { t, v });
  const FLIP = { "ease-in": "ease-out", "ease-out": "ease-in" };
  /** An exit from an entrance: the same moves played backwards (eases flip with them). */
  function mirror(p, id, name) {
    const keys = {};
    for (const [ch, list] of Object.entries(p.keys)) {
      const rev = list.map((x, i) => ({ t: r4(p.length - x.t), v: x.v, ease: i + 1 < list.length ? list[i + 1].ease : undefined })).reverse();
      keys[ch] = rev.map((x) => (x.ease && x.ease !== "ease-in-out" ? { t: x.t, v: x.v, ease: FLIP[x.ease] || x.ease } : { t: x.t, v: x.v }));
    }
    return { id, name, group: "Out", anchor: "out", length: p.length, keys, ...(p.props ? { props: { ...p.props } } : {}) };
  }

  const IN = [
    { id: "fade-in", name: "Fade in", length: 0.5, keys: { opacity: [k(0, 0), k(0.5, 1)] } },
    { id: "pop-in", name: "Pop in", length: 0.4, keys: { scale: [k(0, 0), k(0.25, 1.12, "ease-out"), k(0.4, 1)], opacity: [k(0, 0), k(0.12, 1)] } },
    { id: "slide-up-in", name: "Slide up", length: 0.6, keys: { y: [k(0, 120), k(0.6, 0, "ease-out")], opacity: [k(0, 0), k(0.3, 1)] } },
    { id: "slide-down-in", name: "Slide down", length: 0.6, keys: { y: [k(0, -120), k(0.6, 0, "ease-out")], opacity: [k(0, 0), k(0.3, 1)] } },
    { id: "slide-left-in", name: "Slide in from the right", length: 0.6, keys: { x: [k(0, 400), k(0.6, 0, "ease-out")], opacity: [k(0, 0), k(0.3, 1)] } },
    { id: "slide-right-in", name: "Slide in from the left", length: 0.6, keys: { x: [k(0, -400), k(0.6, 0, "ease-out")], opacity: [k(0, 0), k(0.3, 1)] } },
    { id: "drop-in", name: "Drop and bounce", length: 0.8, keys: { y: [k(0, -500), k(0.45, 0, "ease-in"), k(0.6, -40, "ease-out"), k(0.8, 0, "ease-in")], opacity: [k(0, 0), k(0.1, 1)] } },
    { id: "zoom-in", name: "Zoom in", length: 0.6, keys: { scale: [k(0, 1.6), k(0.6, 1, "ease-out")], opacity: [k(0, 0), k(0.35, 1)], blur: [k(0, 14), k(0.6, 0, "ease-out")] } },
    { id: "spin-in", name: "Spin in", length: 0.7, keys: { rotation: [k(0, -180), k(0.7, 0, "ease-out")], scale: [k(0, 0), k(0.7, 1, "ease-out")], opacity: [k(0, 0), k(0.2, 1)] } },
    { id: "whip-in", name: "Whip in", length: 0.45, keys: { x: [k(0, -1400), k(0.45, 0, "ease-out")] }, props: { motionBlur: 180 } },
    { id: "rise-blur", name: "Rise and focus", length: 0.8, keys: { y: [k(0, 40), k(0.8, 0, "ease-out")], blur: [k(0, 16), k(0.8, 0, "ease-out")], opacity: [k(0, 0), k(0.5, 1)] } },
    { id: "draw-on", name: "Draw on (shapes)", length: 1, keys: { trimEnd: [k(0, -100), k(1, 0, "ease-out")] } },
  ].map((p) => ({ ...p, group: "In", anchor: "in" }));
  const OUT = [
    mirror(IN[0], "fade-out", "Fade out"),
    mirror(IN[1], "pop-out", "Pop out"),
    mirror(IN[3], "slide-up-out", "Slide out up"),
    mirror(IN[2], "slide-down-out", "Slide out down"),
    mirror(IN[5], "slide-left-out", "Slide out to the left"),
    mirror(IN[4], "slide-right-out", "Slide out to the right"),
    mirror(IN[7], "zoom-out", "Zoom out"),
    mirror(IN[8], "spin-out", "Spin out"),
    { ...mirror(IN[9], "whip-out", "Whip out"), keys: { x: [k(0, 0), k(0.45, 1400, "ease-in")] } },
    mirror(IN[10], "sink-blur", "Sink and blur"),
    mirror(IN[11], "draw-off", "Draw off (shapes)"),
  ];
  const AT = [
    { id: "pulse", name: "Pulse", length: 0.4, keys: { scale: [k(0, 1), k(0.15, 1.12, "ease-out"), k(0.4, 1)] } },
    { id: "shake", name: "Shake", length: 0.35, keys: { x: [k(0, 0), k(0.05, -18), k(0.1, 16), k(0.15, -12), k(0.2, 8), k(0.27, -4), k(0.35, 0)] } },
    { id: "wobble", name: "Wobble", length: 0.5, keys: { rotation: [k(0, 0), k(0.12, -8, "ease-out"), k(0.3, 6), k(0.5, 0)] } },
    { id: "bounce", name: "Bounce", length: 0.65, keys: { y: [k(0, 0), k(0.2, -60, "ease-out"), k(0.4, 0, "ease-in"), k(0.52, -18, "ease-out"), k(0.65, 0, "ease-in")] } },
    { id: "flash", name: "Flash", length: 0.4, keys: { brightness: [k(0, 0), k(0.06, 80), k(0.4, 0, "ease-out")] } },
  ].map((p) => ({ ...p, group: "Emphasis", anchor: "at" }));
  /* Loops are generated for the clip's length, a whole number of cycles. */
  const cycles = (dur, period) => Math.max(1, Math.round(dur / period));
  /** Keys stepping through `values` over and over, `steps` per cycle, ending where they began. */
  const cycle = (dur, period, values) => {
    const n = cycles(dur, period) * values.length, out = [];
    for (let i = 0; i <= n; i++) out.push(k(r4(i * dur / n), values[i % values.length]));
    return out;
  };
  const LOOP = [
    { id: "float", name: "Float", gen: (dur) => ({ y: cycle(dur, 2.4, [0, -14]) }) },
    { id: "breathe", name: "Breathe", gen: (dur) => ({ scale: cycle(dur, 1.2, [1, 1.06]) }) },
    { id: "sway", name: "Sway", gen: (dur) => ({ rotation: cycle(dur, 2.4, [0, -6, 0, 6]) }) },
    { id: "spin", name: "Spin", gen: (dur) => ({ rotation: [k(0, 0), k(r4(dur), 360 * cycles(dur, 4), "linear")] }) },
    { id: "wiggle", name: "Wiggle", gen: (dur) => {
      // a fixed pseudo-random walk, so the same clip wiggles the same way every time
      let s = 7;
      const rnd = () => ((s = (s * 16807) % 2147483647) / 2147483647) * 2 - 1;
      const n = Math.max(2, Math.round(dur / 0.12)), x = [k(0, 0)], y = [k(0, 0)];
      for (let i = 1; i < n; i++) { const t = r4(i * dur / n); x.push(k(t, r4(rnd() * 10))); y.push(k(t, r4(rnd() * 10))); }
      x.push(k(r4(dur), 0)); y.push(k(r4(dur), 0));
      return { x, y };
    } },
  ].map((p) => ({ ...p, group: "Loop", anchor: "whole" }));
  const PRESETS = [...IN, ...OUT, ...AT, ...LOOP];

  /** A preset, validated. strict: throw on bad input (agent / saved file). */
  function normalizePreset(p, strict = false) {
    const bad = (m) => { if (strict) throw new Error(m); return null; };
    if (!isObj(p)) return bad("a preset is an object like {name, anchor, length, keys:{channel:[{t, v}]}}");
    const name = typeof p.name === "string" && p.name.trim() ? p.name.trim().slice(0, 60) : null;
    const id = slug(p.id || name);
    if (!id) return bad("a preset needs a name");
    const anchor = p.anchor || "in";
    if (!ANCHORS.includes(anchor)) return bad(`preset ${id}: anchor is ${ANCHORS.join(" | ")}`);
    const length = anchor === "whole" ? 1 : p.length;
    if (!isNum(length) || length <= 0 || length > 60) return bad(`preset ${id}: length is seconds, more than 0`);
    if (!isObj(p.keys) || !Object.keys(p.keys).length) return bad(`preset ${id}: keys is {channel: [{t, v, ease?}, …]}`);
    const keys = {};
    for (const [ch, list] of Object.entries(p.keys)) {
      if (!CHANNELS.includes(ch)) return bad(`preset ${id}: ${ch} can't be animated by a preset (${CHANNELS.join(", ")})`);
      if (!Array.isArray(list) || !list.length) return bad(`preset ${id}: keys.${ch} must be a list of {t, v, ease?}`);
      const out = [];
      for (const x of list) {
        if (!isObj(x) || !isNum(x.t) || !isNum(x.v) || x.t < 0 || x.t > length + EPS) return bad(`preset ${id}: keys.${ch} times run 0…${anchor === "whole" ? "1 (fractions of the clip)" : length}`);
        if (x.ease != null && !EASES.includes(x.ease)) return bad(`preset ${id}: ease is ${EASES.join(" | ")}`);
        out.push(x.ease && x.ease !== "ease-in-out" ? k(r4(x.t), r4(x.v), x.ease) : k(r4(x.t), r4(x.v)));
      }
      keys[ch] = out.sort((a, b) => a.t - b.t);
    }
