      hold: isNum(hold) ? hold : comp.template && isNum(comp.template.hold) ? comp.template.hold : comp.duration,
      background: comp.background, tracks: comp.tracks, clips: comp.clips,
      media: media.filter((m) => used.has(m.id)),
