      if (!still && fps > 0 && fps < 1000) out.fps = round(fps, 3);
    }
    if (a) {
      if (a.codec_name) out.audioCodec = String(a.codec_name);
      const ch = Number(a.channels);
      if (ch > 0) out.audioChannels = ch;
      const sr = Number(a.sample_rate);
