    if (f === "used") return uses > 0;
    if (f === "unused") return uses === 0;
    if (f.startsWith("kind:")) return m.kind === f.slice(5);
    if (f.startsWith("tag:")) { const t = f.slice(4).toLowerCase(); return (m.tags || []).some((x) => x.toLowerCase() === t); }
