  const FIXED_MBPS = { prores: { proxy: 45, lt: 102, standard: 147, hq: 220, 4444: 330, "4444xq": 500 }, dnxhr: { lb: 45, sq: 145, hq: 220, hqx: 220, 444: 440 } };
