    const mbps = next.webCodecsBitrateMbps;
    if (mbps != null) {
      const n = Number(mbps);
      next.webCodecsBitrateMbps = (Number.isFinite(n) && n > 0) ? n : null;
    }
    if (next.webCodecsBitrateMode !== "constant" && next.webCodecsBitrateMode !== "variable") {
      next.webCodecsBitrateMode = "variable";
