    next.snapTargets = { ...DEFAULT_SETTINGS.snapTargets };
    if (st && typeof st === "object") {
      for (const k of Object.keys(next.snapTargets)) if (typeof st[k] === "boolean") next.snapTargets[k] = st[k];
