    const max = new Float32Array(n);
    for (let i = 0; i < n; i++) {
      let mx = 0;
      for (const p of channels) if (p[i] > mx) mx = p[i];
      max[i] = mx;
    }
    runtime.wavePeaks.set(m.id, { src, channels, max });
    if (m.channels == null) m.channels = buf.numberOfChannels;
