  state.gesture = true;
  const seek = (ev) => setTime(timeAtEvent(ev));
  seek(e);
  const onUp = () => {
    window.removeEventListener("pointermove", seek);
    window.removeEventListener("pointerup", onUp);
    state.gesture = false;
    if (runtime.pendingSync) syncFromServer();
