    if (moved && mk.t !== t0) {
      runtime.undo.push(snapshot);
      if (runtime.undo.length > 100) runtime.undo.shift();
      runtime.redo.length = 0;
      project.markers.sort((a, b) => a.t - b.t);
      scheduleSave();
